"""Stage owned files only; no production changes or MMIO."""
import base64,gzip,hashlib,json
from pathlib import Path
assert Path('/proc/sys/kernel/random/boot_id').read_text().strip()=='3e1add36-b917-4289-91dc-699348528782'
p=Path('/home/root/aura-pan-manual-ui-20261020/staged-v1');p.mkdir(parents=True,exist_ok=False)
for name,packed,expected in [('payload.json', '', '9ce33787c97e1580174f006be8d253bab51e43a0f5e554785f06eb815453a2f4'), ('deploy.py', '', '1f604698af21788bf4ecc17d1f12bdad45a6f78ade0a7d7afd1dbf5e6e13cb3e')]:
 raw=gzip.decompress(base64.b64decode(packed));assert hashlib.sha256(raw).hexdigest()==expected
 with (p/name).open('xb') as stream:stream.write(raw)
print(json.dumps({'status':'STAGED_NO_PRODUCTION_CHANGE_NO_ACTUATION','path':str(p)}),flush=True)
